rcl_interfaces::msg::SetParametersResult RadarObjectFusionToDetectedObjectNode::onSetParam(
  const std::vector<rclcpp::Parameter> & params)
{
  rcl_interfaces::msg::SetParametersResult result;

  try {
    // Node Parameter
    {
      auto & p = node_param_;

      // Update params
      update_param(params, "node_params.update_rate_hz", p.update_rate_hz);
    }

    // Core Parameter
    {
      // Copy to local variable
      auto & p = core_param_;

      // Update params
      update_param(params, "core_params.bounding_box_margin", p.bounding_box_margin);
      update_param(params, "core_params.split_threshold_velocity", p.split_threshold_velocity);
      update_param(params, "core_params.threshold_yaw_diff", p.threshold_yaw_diff);
      update_param(params, "core_params.velocity_weight_average", p.velocity_weight_average);
      update_param(params, "core_params.velocity_weight_median", p.velocity_weight_median);
      update_param(
        params, "core_params.velocity_weight_target_value_average",
        p.velocity_weight_target_value_average);
      update_param(
        params, "core_params.velocity_weight_target_value_top", p.velocity_weight_target_value_top);
      update_param(params, "core_params.convert_doppler_to_twist", p.convert_doppler_to_twist);
      update_param(params, "core_params.threshold_probability", p.threshold_probability);
      update_param(params, "core_params.compensate_probability", p.compensate_probability);

      // Set parameter to instance
      if (radar_fusion_to_detected_object_) {
        radar_fusion_to_detected_object_->setParam(core_param_);
      }
    }
  } catch (const rclcpp::exceptions::InvalidParameterTypeException & e) {
    result.successful = false;
    result.reason = e.what();
    return result;
  }

  result.successful = true;
  result.reason = "success";
  return result;
}

bool update_param(
  const std::vector<rclcpp::Parameter> & params, const std::string & name, T & value)
{
  const auto itr = std::find_if(
    params.cbegin(), params.cend(),
    [&name](const rclcpp::Parameter & p) { return p.get_name() == name; });

  // Not found
  if (itr == params.cend()) {
    return false;
  }

  value = itr->template get_value<T>();
  return true;
}

bool update_param(
  const std::vector<rclcpp::Parameter> & params, const std::string & name, T & value)
{
  const auto itr = std::find_if(
    params.cbegin(), params.cend(),
    [&name](const rclcpp::Parameter & p) { return p.get_name() == name; });

  // Not found
  if (itr == params.cend()) {
    return false;
  }

  value = itr->template get_value<T>();
  return true;
}

void RadarFusionToDetectedObject::setParam(const Param & param)
{
  // Radar fusion param
  param_.bounding_box_margin = param.bounding_box_margin;
  param_.split_threshold_velocity = param.split_threshold_velocity;
  param_.threshold_yaw_diff = param.threshold_yaw_diff;

  // Normalize weight param
  double sum_weight = param.velocity_weight_median + param.velocity_weight_min_distance +
                      param.velocity_weight_average + param.velocity_weight_target_value_average +
                      param.velocity_weight_target_value_top;

  if (sum_weight < 0.01) {
    param_.velocity_weight_min_distance = 1.0;
    param_.velocity_weight_median = 0.0;
    param_.velocity_weight_average = 0.0;
    param_.velocity_weight_target_value_average = 0.0;
    param_.velocity_weight_target_value_top = 0.0;
  } else {
    param_.velocity_weight_min_distance = param.velocity_weight_min_distance / sum_weight;
    param_.velocity_weight_median = param.velocity_weight_median / sum_weight;
    param_.velocity_weight_average = param.velocity_weight_average / sum_weight;
    param_.velocity_weight_target_value_average =
      param.velocity_weight_target_value_average / sum_weight;
    param_.velocity_weight_target_value_top = param.velocity_weight_target_value_top / sum_weight;
  }

  // Parameters for fixing object information
  param_.threshold_probability = param.threshold_probability;
  param_.convert_doppler_to_twist = param.convert_doppler_to_twist;
  param_.compensate_probability = param.compensate_probability;
}
